import { describe, expect, it } from 'vitest';

import { honours, passed } from './grade.js';

describe('grade', () => {
  it('pins the pass boundary on both sides', () => {
    expect(passed(50)).toBe(true);
    expect(passed(49)).toBe(false);
  });

  it('checks honours away from its boundary only', () => {
    expect(honours(100)).toBe(true);
    expect(honours(10)).toBe(false);
  });
});
